using System;using System.Linq;using System.Collections.Generic;using Mono.Cecil;using Mono.Cecil.Cil;
class VerifyIL {
 static int Count(StackBehaviour s){switch(s){case StackBehaviour.Pop0:case StackBehaviour.Push0:return 0;case StackBehaviour.Pop1:case StackBehaviour.Popi:case StackBehaviour.Popref:case StackBehaviour.Push1:case StackBehaviour.Pushi:case StackBehaviour.Pushi8:case StackBehaviour.Pushr4:case StackBehaviour.Pushr8:case StackBehaviour.Pushref:return 1;case StackBehaviour.Pop1_pop1:case StackBehaviour.Popi_pop1:case StackBehaviour.Popi_popi:case StackBehaviour.Popi_popi8:case StackBehaviour.Popi_popr4:case StackBehaviour.Popi_popr8:case StackBehaviour.Popref_pop1:case StackBehaviour.Popref_popi:case StackBehaviour.Push1_push1:return 2;case StackBehaviour.Popi_popi_popi:case StackBehaviour.Popref_popi_popi:case StackBehaviour.Popref_popi_popi8:case StackBehaviour.Popref_popi_popr4:case StackBehaviour.Popref_popi_popr8:case StackBehaviour.Popref_popi_popref:return 3;default:throw new Exception("Unknown stack behaviour "+s);}}
 static void Check(MethodDefinition m){var seen=new Dictionary<Instruction,int>();var queue=new Queue<KeyValuePair<Instruction,int>>();Action<Instruction,int> Add=(i,n)=>{if(i!=null)queue.Enqueue(new KeyValuePair<Instruction,int>(i,n));};Add(m.Body.Instructions.First(),0);foreach(var e in m.Body.ExceptionHandlers){Add(e.HandlerStart,e.HandlerType==ExceptionHandlerType.Catch||e.HandlerType==ExceptionHandlerType.Filter?1:0);if(e.FilterStart!=null)Add(e.FilterStart,1);}
  while(queue.Count>0){var item=queue.Dequeue();var i=item.Key;int depth=item.Value,prior;if(seen.TryGetValue(i,out prior)){if(prior!=depth)throw new Exception(m.FullName+" inconsistent stack at "+i+": "+prior+" / "+depth);continue;}seen[i]=depth;int pop,push;
   if(i.OpCode.StackBehaviourPop==StackBehaviour.Varpop){if(i.OpCode==OpCodes.Ret)pop=m.ReturnType.MetadataType==MetadataType.Void?0:1;else if(i.Operand is MethodReference){var method=(MethodReference)i.Operand;pop=method.Parameters.Count+(method.HasThis&&i.OpCode!=OpCodes.Newobj?1:0);}else if(i.Operand is CallSite){var call=(CallSite)i.Operand;pop=call.Parameters.Count+(call.HasThis?1:0)+1;}else throw new Exception("Unknown varpop "+i);}else pop=i.OpCode.StackBehaviourPop==StackBehaviour.PopAll?depth:Count(i.OpCode.StackBehaviourPop);
   if(i.OpCode.StackBehaviourPush==StackBehaviour.Varpush){var method=i.Operand as MethodReference;var call=i.Operand as CallSite;push=(method!=null?method.ReturnType:call.ReturnType).MetadataType==MetadataType.Void?0:1;}else push=Count(i.OpCode.StackBehaviourPush);
   if(depth<pop)throw new Exception(m.FullName+" stack underflow at "+i);int after=depth-pop+push;if(i.OpCode==OpCodes.Ret){if(after!=0)throw new Exception(m.FullName+" unbalanced return "+after);continue;}
   if(i.OpCode==OpCodes.Leave||i.OpCode==OpCodes.Leave_S)after=0;
   if(i.OpCode==OpCodes.Endfinally||i.OpCode==OpCodes.Endfilter||i.OpCode.FlowControl==FlowControl.Throw)continue;
   if(i.Operand is Instruction)Add((Instruction)i.Operand,after);if(i.Operand is Instruction[])foreach(var target in (Instruction[])i.Operand)Add(target,after);
   if(i.OpCode.FlowControl!=FlowControl.Branch)Add(i.Next,after);
  }
 }
 static void Main(string[] args){var resolver=new DefaultAssemblyResolver();resolver.AddSearchDirectory(args[1]);var a=AssemblyDefinition.ReadAssembly(args[0],new ReaderParameters{AssemblyResolver=resolver});int checkedMethods=0;
 foreach(var t in a.MainModule.Types)foreach(var m in t.Methods){if(!m.HasBody)continue;if(!m.Body.Instructions.Any(i=>i.Operand is MethodReference && ((MethodReference)i.Operand).DeclaringType.Scope.Name=="RebellionRules"))continue;Check(m);checkedMethods++;}
 if(checkedMethods<20)throw new Exception("Too few injected method bodies");Console.WriteLine("Verified "+checkedMethods+" hooked method stack graphs.");
 var types=a.MainModule.Types;Func<string,string,MethodDefinition> Find=(t,n)=>types.Single(x=>x.Name==t).Methods.Single(x=>x.Name==n);
 Func<MethodDefinition,string,int> Calls=(m,n)=>m.Body.Instructions.Count(i=>i.Operand is MethodReference&&((MethodReference)i.Operand).Name==n);
 foreach(var name in new[]{"addMoney","spendMoney"})if(Find("Actor",name).Body.Instructions.Any(i=>i.Operand is MethodReference&&new[]{"PayNativeSalary","RecordSpend","FundNativeIncome","EarnNativeIncome"}.Contains(((MethodReference)i.Operand).Name)))throw new Exception("Global money interception remains");
 foreach(var t in new[]{"BehClaimZoneForCityActorBorder","BehGenerateLootFromHouse","BehBuildTarget","BehCityActorCreateRoad","BehCityActorFertilizeCrop","BehGetResourcesFromMine","BehMakeFarm","BehPlantCrops","BehRemoveRuins","BehThrowResources"})if(types.Single(x=>x.Name==t).Methods.Sum(m=>m.HasBody?Calls(m,"Earn"):0)==0)throw new Exception("Unfunded production source "+t);
 if(Calls(Find("BehFinishTalk","makeGift"),"PrepareGift")!=1||Calls(Find("BehFinishReading","execute"),"AfterReading")!=Find("BehFinishReading","execute").Body.Instructions.Count(i=>i.OpCode==OpCodes.Ret)||Calls(Find("PlotManager","newPlot"),"SpendPolitics")!=1)throw new Exception("Missing specific money/reading event");
 foreach(var name in new[]{"payTaxToLeader","payTributeToKing"})if(Find("BehActorGiveTax",name).Body.Instructions.Any(i=>i.Operand is MethodReference&&((MethodReference)i.Operand).DeclaringType.Scope.Name=="RebellionRules"))throw new Exception("Native tax distribution was unexpectedly changed");
 Console.WriteLine("Verified native income, gift, tax, expense and reading routing.");
 foreach(var pair in new[]{new[]{"CityBehSupplyKingdomCities","shareResource","Supply"},new[]{"CityBehProduceResources","tryToProduce","Produced"},new[]{"BehBoatMakeTrade","execute","BoatTrade"},new[]{"SuccessionTool","getKingFromRoyalClan","RoyalHeir"},new[]{"SuccessionTool","getKingFromLeaders","LeaderHeir"},new[]{"Alliance","update","UpdateAlliance"},new[]{"Alliance","leave","LeaveAlliance"},new[]{"Alliance","dissolve","DissolveAlliance"},new[]{"Item","setUnitHasIt","ItemOwner"},new[]{"Item","setInCityStorage","ItemStorage"},new[]{"Item","getDamaged","Wear"},new[]{"Item","reforge","Reforged"},new[]{"Subspecies","genesChangedEvent","GenomeChanged"},new[]{"Actor","getConstructionSpeed","Construction"}})if(Calls(Find(pair[0],pair[1]),pair[2])==0)throw new Exception("Missing native system adapter "+pair[2]);
 if(Calls(Find("BehBoatMakeTrade","execute"),"addToInventory")!=0)throw new Exception("Unfunded dock gold creation remains");
 foreach(var pair in new[]{new[]{"CityBehCheckCitizenTasks","execute","MilitaryJobs"},new[]{"City","checkCanMakeWarrior","CanRecruit"},new[]{"City","checkIfWarriorStillOk","CanRemain"},new[]{"City","isOkToSendArmy","CanDeploy"},new[]{"City","tryToMakeWarrior","RecruitResult"},new[]{"DiplomacyHelpers","isWarNeeded","WarNeeded"},new[]{"War","newWar","WarCreated"},new[]{"ItemLibrary","init","InitWeapons"},new[]{"Actor","tryToAttack","AmmoReady"},new[]{"Actor","tryToAttack","Shot"},new[]{"ItemCrafting","craftItem","EquipmentMade"}})if(Calls(Find(pair[0],pair[1]),pair[2])==0)throw new Exception("Missing lifecycle adapter "+pair[2]);
 Console.WriteLine("Verified military jobs, recruitment, deployment, rebellion identity, industrial weapons and ammunition routing.");
 foreach(var name in new[]{"isUnlocked","isAvailable","isUnlockedByPlayer"})if(Calls(Find("BaseUnlockableAsset",name),"Target")!=1)throw new Exception("Missing unlock availability gate "+name);
 if(Calls(Find("ItemLibrary","fillUnlockedPools"),"EquipmentPools")!=1||Calls(Find("GameProgress","loadData"),"Apply")<1)throw new Exception("Missing native unlock pool/load routing");
 var helper=AssemblyDefinition.ReadAssembly(System.IO.Path.Combine(System.IO.Path.GetDirectoryName(args[0]),"RebellionRules.dll"));
 foreach(var type in helper.MainModule.Types)foreach(var method in type.Methods){if(!method.HasBody)continue;foreach(var ins in method.Body.Instructions){var call=ins.Operand as MethodReference;if(call==null)continue;
  if(call.DeclaringType.Name=="GodEconomy"&&call.Name=="Exchange"&&!(type.Name=="GodWorldRuntime"&&method.Name=="ExchangeCore")&&!(type.Name=="NativeLifecycle"&&method.Name=="NationalOperation"))throw new Exception("Automatic GOD exchange remains: "+method.FullName);
  if(call.Name=="ExchangeCore"&&!(type.Name=="GodWorldRuntime"&&method.Name=="Exchange"))throw new Exception("Unrequested city exchange remains: "+method.FullName);
  if(call.Name=="ExchangePersonal"&&type.Name!="GodCurrencyEditorPanel")throw new Exception("Automatic personal exchange remains: "+method.FullName);
 }}
 var spending=new[]{"CanPayPublic","EnsurePublicLiquidity","FundNativeIncome","RewardWork","EnsureBuildLiquidity","LiquidPayment","CanAfford","Manufacture","ComputeTarget","IndustrialTrade","NationalYear","Worth"};
 foreach(var type in helper.MainModule.Types)foreach(var method in type.Methods.Where(m=>m.HasBody&&spending.Contains(m.Name)))if(method.Body.Instructions.Any(i=>i.Operand is MethodReference&&new[]{"GetGod","PersonalGod","Exchange","ExchangeCore","ExchangePersonal"}.Contains(((MethodReference)i.Operand).Name)))throw new Exception("GOD remains a development payment source: "+method.FullName);
 if(Calls(Find("AssetManager","initLibs"),"AssetsReady")<1)throw new Exception("Missing deferred unlock initialization");
 foreach(var window in new[]{"CityWindow","KingdomWindow","FamilyWindow","ClanWindow","AllianceWindow","CultureWindow","ReligionWindow","LanguageWindow","SubspeciesWindow"})if(Calls(Find(window,"showStatsRows"),"Show")<1)throw new Exception("Missing organization editor/ranking "+window);
 if(Calls(Find("MapBox","updateFinish"),"Tick")<1||Calls(Find("Kingdom","getTaxRateLocal"),"TaxLocal")<1||Calls(Find("Kingdom","getTaxRateTribute"),"TaxTribute")<1)throw new Exception("Missing ranking scheduler or live tax policy");
 foreach(var type in helper.MainModule.Types.Where(t=>t.Name!="OrganizationTests"))foreach(var method in type.Methods.Where(m=>m.HasBody))if(method.Body.Instructions.Any(i=>i.OpCode==OpCodes.Ldstr&&i.Operand is string&&((string)i.Operand).StartsWith("god_skill_xp_")))throw new Exception("Parallel personal skill XP remains: "+method.FullName);
 foreach(var type in types)if(type.Name.EndsWith("Library"))foreach(var method in type.Methods.Where(m=>m.HasBody&&new[]{"init","post_init","linkAssets"}.Contains(m.Name)))if(Calls(method,"Apply")>0)throw new Exception("Bulk unlock still runs inside partial library initialization: "+method.FullName);
 foreach(var spec in new[]{new[]{"City","joinAnotherKingdom","3"},new[]{"Kingdom","setKing","2"},new[]{"Kingdom","removeKing","0"},new[]{"Kingdom","getAlliance","0"},new[]{"City","setLeader","2"},new[]{"Clan","chiefLeft","0"},new[]{"Clan","setChief","1"},new[]{"Family","setAlpha","2"},new[]{"Alliance","join","3"},new[]{"Alliance","leave","2"},new[]{"Actor","joinCity","1"},new[]{"Actor","joinKingdom","1"},new[]{"Actor","setFamily","1"},new[]{"Actor","setClan","1"},new[]{"Actor","setCulture","1"},new[]{"Actor","setReligion","1"},new[]{"Actor","joinLanguage","1"},new[]{"Actor","setSubspecies","1"},new[]{"NanoObject","setName","2"}})if(!types.Single(t=>t.Name==spec[0]).Methods.Any(m=>m.Name==spec[1]&&m.Parameters.Count==Int32.Parse(spec[2])))throw new Exception("Missing native organization edit API "+String.Join(".",spec));
 Console.WriteLine("Verified nine organization editors, dynamic ranking scheduler, native taxes and removal of custom personal skill XP.");
 Console.WriteLine("Verified all equipment/personal-trait unlock gates and gold-only development payment boundaries.");
 Console.WriteLine("Verified production, shipping, diplomacy, succession, equipment and genome routing.");}
}
